// ── Types ────────────────────────────────────────────────────────────────────
interface ScatterPt {
  fi: number;
  netrtg: number;
  team: string;
  date: string;
  opponent: string;
  isWin?: boolean;
  home_away: string;
  rest_days?: number;
  travel_miles?: number;
  tz_crossed?: number;
}
interface CurvePt { x: number; y: number; }
interface TooltipInfo { x: number; y: number; pt: ScatterPt; }

// ── Constants ────────────────────────────────────────────────────────────────
const MARGIN = { top: 24, right: 32, bottom: 52, left: 56 };
const W = 960;
const H = 420;
const IW = W - MARGIN.left - MARGIN.right;
const IH = H - MARGIN.top - MARGIN.bottom;

const TEAM_COLORS: Record<string, string> = {
  ATL:"#C8102E",BOS:"#007A33",BKN:"#aaaaaa",CHA:"#1D1160",CHI:"#CE1141",
  CLE:"#860038",DAL:"#00538C",DEN:"#FEC524",DET:"#C8102E",GSW:"#1D428A",
  HOU:"#CE1141",IND:"#FDBB30",LAC:"#C8102E",LAL:"#FDB927",MEM:"#5D76A9",
  MIA:"#98002E",MIL:"#00471B",MIN:"#78BE20",NOP:"#0C2340",NYK:"#F58426",
  OKC:"#007AC1",ORL:"#0077C0",PHI:"#006BB6",PHX:"#E56020",POR:"#E03A3E",
  SAC:"#5A2D81",SAS:"#C4CED4",TOR:"#CE1141",UTA:"#F9A01B",WAS:"#E31837",
};

const TEAM_NAMES: Record<string, string> = {
  ATL:"Atlanta Hawks",BOS:"Boston Celtics",BKN:"Brooklyn Nets",CHA:"Charlotte Hornets",
  CHI:"Chicago Bulls",CLE:"Cleveland Cavaliers",DAL:"Dallas Mavericks",DEN:"Denver Nuggets",
  DET:"Detroit Pistons",GSW:"Golden State Warriors",HOU:"Houston Rockets",IND:"Indiana Pacers",
  LAC:"LA Clippers",LAL:"Los Angeles Lakers",MEM:"Memphis Grizzlies",MIA:"Miami Heat",
  MIL:"Milwaukee Bucks",MIN:"Minnesota Timberwolves",NOP:"New Orleans Pelicans",NYK:"New York Knicks",
  OKC:"Oklahoma City Thunder",ORL:"Orlando Magic",PHI:"Philadelphia 76ers",PHX:"Phoenix Suns",
  POR:"Portland Trail Blazers",SAC:"Sacramento Kings",SAS:"San Antonio Spurs",TOR:"Toronto Raptors",
  UTA:"Utah Jazz",WAS:"Washington Wizards",
};

function fmt(v: number | null | undefined, dec = 1) {
  return v == null ? "—" : v.toFixed(dec);
}

// ── Component ────────────────────────────────────────────────────────────────
export default function FatigueScatterPlot({ highlightTeam = "" }: { highlightTeam?: string }) {
  const [filterTeam, setFilterTeam] = useState<string>("ALL");
  const [scatterRawData, setScatterRawData] = useState<Record<string, unknown>[]>([]);
  const [selectedSeason, setSelectedSeason] = useState<string>("");
  const [tooltip, setTooltip]       = useState<TooltipInfo | null>(null);
  const [hoveredPt, setHoveredPt]   = useState<ScatterPt | null>(null);
  const svgRef = useRef<SVGSVGElement>(null);

  useEffect(() => {
    d3.csv("/data/team_game_master_2015-2025.csv").then((rows) => {
      setScatterRawData(rows);
      if (rows.length > 0) {
        const seasons = [...new Set(rows.map((r) => String(r.season ?? "").replace(/^"|"$/g, "")).filter(Boolean))].sort().reverse();
        if (seasons.length) setSelectedSeason((s) => s || seasons[0]);
      }
    }).catch(console.error);
  }, []);

  const seasons = useMemo(() => {
    return [...new Set(scatterRawData.map((r) => String(r.season ?? "").replace(/^"|"$/g, "")).filter(Boolean))].sort().reverse();
  }, [scatterRawData]);

  const allPts = useMemo(() => {
    if (!scatterRawData.length) return SCATTER_DATA as ScatterPt[];
    const parseNum = (v: string | undefined): number | undefined => {
      if (v == null || v === "" || String(v).toUpperCase() === "NA") return undefined;
      const n = Number(v);
      return Number.isFinite(n) ? n : undefined;
    };
    const pts: ScatterPt[] = [];
    for (const r of scatterRawData) {
      const season = String(r.season ?? "").replace(/^"|"$/g, "");
      if (selectedSeason && season !== selectedSeason) continue;
      const fi = parseNum(r.fatigue_index as string);
      const netrtg = parseNum(r.netrtg as string);
      if (fi == null || !Number.isFinite(fi) || netrtg == null || !Number.isFinite(netrtg)) continue;
      const team = String(r.team_slug ?? "").trim();
      if (!team) continue;
      const restHours = parseNum(r.rest_hours as string);
      pts.push({
        fi,
        netrtg,
        team,
        date: String(r.game_date ?? ""),
        opponent: String(r.opponent_slug ?? ""),
        isWin: String(r.wl ?? "").toUpperCase() === "W",
        home_away: String(r.location ?? ""),
        rest_days: restHours != null ? restHours / 24 : undefined,
        travel_miles: parseNum(r.miles_leg as string),
        tz_crossed: parseNum(r.tz_crossed as string),
      });
    }
    return pts;
  }, [scatterRawData, selectedSeason]);
  const loessAll: CurvePt[]                    = LOESS_DATA.all;
  const loessTeams: Record<string, CurvePt[]>  = LOESS_DATA.teams;

  const teams = useMemo(() => {
    const s = Array.from(new Set(allPts.map(p => p.team))).sort();
    return s;
  }, [allPts]);

  const visiblePts = useMemo(() =>
    filterTeam === "ALL" ? allPts : allPts.filter(p => p.team === filterTeam),
    [allPts, filterTeam]
  );

  const curve: CurvePt[] = useMemo(() => {
    if (filterTeam !== "ALL" && loessTeams[filterTeam]) return loessTeams[filterTeam];
    return loessAll;
  }, [filterTeam, loessAll, loessTeams]);

  // Scales
  const xScale = useMemo(() =>
    d3.scaleLinear().domain([0, 85]).range([0, IW]).nice(),
    []
  );
  const yScale = useMemo(() =>
    d3.scaleLinear().domain([-65, 60]).range([IH, 0]).nice(),
    []
  );

  // D3 line for LOESS curve
  const lineGen = useMemo(() =>
    d3.line<CurvePt>()
      .x(d => xScale(d.x))
      .y(d => yScale(d.y))
      .curve(d3.curveCatmullRom),
    [xScale, yScale]
  );

  // X axis ticks
  const xTicks = xScale.ticks(9);
  const yTicks = yScale.ticks(8);

  // Active team color
  const activeColor = filterTeam !== "ALL" ? (TEAM_COLORS[filterTeam] ?? "#f59e0b") : "#f59e0b";

  function handleDotHover(e: React.MouseEvent<SVGCircleElement>, pt: ScatterPt) {
    const rect = svgRef.current?.getBoundingClientRect();
    if (!rect) return;
    setTooltip({ x: e.clientX - rect.left + 14, y: e.clientY - rect.top - 8, pt });
    setHoveredPt(pt);
  }

  // Summary stats for current filter
  const stats = useMemo(() => {
    if (!visiblePts.length) return null;
    const lowFi  = visiblePts.filter(p => p.fi < 30);
    const highFi = visiblePts.filter(p => p.fi >= 60);
    const meanLow  = d3.mean(lowFi.map(p => p.netrtg));
    const meanHigh = d3.mean(highFi.map(p => p.netrtg));
    const corr = (() => {
      const xs = visiblePts.map(p => p.fi);
      const ys = visiblePts.map(p => p.netrtg);
      const mx = d3.mean(xs)!, my = d3.mean(ys)!;
      const num = d3.sum(visiblePts.map((_, i) => (xs[i]-mx)*(ys[i]-my)));
      const den = Math.sqrt(d3.sum(xs.map(x=>(x-mx)**2)) * d3.sum(ys.map(y=>(y-my)**2)));
      return den === 0 ? 0 : num/den;
    })();
    return { meanLow, meanHigh, corr, nLow: lowFi.length, nHigh: highFi.length };
  }, [visiblePts]);

  return (
    <div style={{
      background: "#080e1a",
      fontFamily: "'IBM Plex Mono','Courier New',monospace",
      color: "#e2e8f0",
      padding: "32px 24px 24px",
      borderTop: "1px solid #1e293b",
    }}>

      {/* ── Header ── */}
      <div style={{ display:"flex", alignItems:"flex-start", justifyContent:"space-between", marginBottom:20 }}>
        <div>
          <div style={{ fontSize:10, letterSpacing:"0.25em", color:"#64748b", textTransform:"uppercase", marginBottom:3 }}>
            Correlation Analysis · 2023–24 Season
          </div>
          <h2 style={{ margin:0, fontSize:20, fontWeight:700, color:"#f8fafc", letterSpacing:"-0.02em" }}>
            Fatigue Index vs. Net Rating
          </h2>
          <p style={{ margin:"6px 0 0", fontSize:11, color:"#475569", maxWidth:520 }}>
            Each point is one team-game. The curve is a LOESS regression showing the smoothed trend.
            Higher fatigue consistently correlates with lower net ratings.
          </p>
        </div>

        {/* Stats callouts */}
        {stats && (
          <div style={{ display:"flex", gap:10 }}>
            {([
              ["CORRELATION r", stats.corr.toFixed(3), stats.corr < -0.05 ? "#f87171" : "#94a3b8"],
              [`LOW FATIGUE <30 (n=${stats.nLow})`, `${fmt(stats.meanLow)} NetRtg`, "#38bdf8"],
              [`HIGH FATIGUE ≥60 (n=${stats.nHigh})`, `${fmt(stats.meanHigh)} NetRtg`, "#ef4444"],
            ] as [string,string,string][]).map(([lbl,val,col]) => (
              <div key={lbl} style={{
                background:"#0f172a", border:"1px solid #1e293b", borderRadius:6,
                padding:"6px 12px", textAlign:"center", minWidth:120
              }}>
                <div style={{ fontSize:9, color:"#475569", letterSpacing:"0.08em", lineHeight:1.4 }}>{lbl}</div>
                <div style={{ fontSize:15, fontWeight:700, color:col }}>{val}</div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* ── Season & Team filter ── */}
      <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:16, flexWrap:"wrap" }}>
        <span style={{ fontSize:10, color:"#64748b", letterSpacing:"0.1em", marginRight:4 }}>SEASON:</span>
        <select
          value={selectedSeason}
          onChange={e => setSelectedSeason(e.target.value)}
          style={{
            background:"#1e293b", border:"1px solid #334155", color:"#e2e8f0",
            borderRadius:4, padding:"4px 10px", fontFamily:"inherit", fontSize:11, cursor:"pointer"
          }}
        >
          {seasons.length === 0 ? (
            <option value="">Loading…</option>
          ) : (
            seasons.map(s => <option key={s} value={s}>{s}</option>)
          )}
        </select>
        <span style={{ fontSize:10, color:"#64748b", letterSpacing:"0.1em", marginRight:4, marginLeft:12 }}>FILTER TEAM:</span>
        <button
          onClick={() => setFilterTeam("ALL")}
          style={{
            background: filterTeam==="ALL" ? "#f59e0b" : "transparent",
            color: filterTeam==="ALL" ? "#080e1a" : "#64748b",
            border: `1px solid ${filterTeam==="ALL" ? "#f59e0b" : "#334155"}`,
            borderRadius:4, padding:"4px 10px", fontFamily:"inherit",
            fontSize:11, cursor:"pointer", fontWeight: filterTeam==="ALL" ? 700 : 400,
          }}
        >ALL</button>
        {teams.map(t => (
          <button key={t}
            onClick={() => setFilterTeam(t === filterTeam ? "ALL" : t)}
            style={{
              background: filterTeam===t ? (TEAM_COLORS[t] ?? "#f59e0b") : "transparent",
              color: filterTeam===t ? "#ffffff" : "#64748b",
              border: `1px solid ${filterTeam===t ? (TEAM_COLORS[t] ?? "#f59e0b") : "#1e293b"}`,
              borderRadius:4, padding:"4px 8px", fontFamily:"inherit",
              fontSize:10, cursor:"pointer",
            }}
          >{t}</button>
        ))}
      </div>

      {/* ── Chart ── */}
      <div style={{ position:"relative" }}>
        <svg ref={svgRef} width={W} height={H} style={{ display:"block", overflow:"visible" }}>
          <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>

            {/* Grid lines */}
            {yTicks.map(t => (
              <line key={`gy-${t}`}
                x1={0} x2={IW} y1={yScale(t)} y2={yScale(t)}
                stroke={t === 0 ? "#334155" : "#0f172a"}
                strokeWidth={t === 0 ? 1.5 : 1}
              />
            ))}
            {xTicks.map(t => (
              <line key={`gx-${t}`}
                x1={xScale(t)} x2={xScale(t)} y1={0} y2={IH}
                stroke="#0f172a" strokeWidth={1}
              />
            ))}

            {/* Zero reference lines */}
            <line x1={0} x2={IW} y1={yScale(0)} y2={yScale(0)}
              stroke="#334155" strokeWidth={1} strokeDasharray="4,4" />
            <text x={IW + 4} y={yScale(0) + 4} fontSize={9} fill="#475569">0</text>

            {/* Scatter points */}
            <g>
              {visiblePts.map((pt, i) => {
                const cx = xScale(pt.fi);
                const cy = yScale(pt.netrtg);
                const isFiltered = filterTeam !== "ALL";
                const dotColor = isFiltered
                  ? (pt.isWin ? "#4ade80" : "#f87171")
                  : (pt.isWin ? "rgba(74,222,128,0.55)" : "rgba(248,113,113,0.45)");
                const isHovered = hoveredPt === pt;
                return (
                  <circle key={i}
                    cx={cx} cy={cy}
                    r={isHovered ? 7 : isFiltered ? 4 : 3}
                    fill={dotColor}
                    stroke={isHovered ? "#ffffff" : "none"}
                    strokeWidth={isHovered ? 1.5 : 0}
                    opacity={isHovered ? 1 : isFiltered ? 0.75 : 0.45}
                    onMouseMove={e => handleDotHover(e, pt)}
                    onMouseLeave={() => { setTooltip(null); setHoveredPt(null); }}
                    style={{ cursor:"pointer" }}
                  />
                );
              })}
            </g>

            {/* LOESS curve */}
            {curve.length > 1 && (
              <>
                {/* Glow effect */}
                <path
                  d={lineGen(curve) ?? ""}
                  fill="none"
                  stroke={activeColor}
                  strokeWidth={6}
                  opacity={0.15}
                  strokeLinecap="round"
                />
                {/* Main line */}
                <path
                  d={lineGen(curve) ?? ""}
                  fill="none"
                  stroke={activeColor}
                  strokeWidth={2.5}
                  opacity={0.9}
                  strokeLinecap="round"
                />
              </>
            )}

            {/* Fatigue zone annotations */}
            <g opacity={0.5}>
              <rect x={xScale(0)} y={0} width={xScale(30)-xScale(0)} height={IH}
                fill="#38bdf8" opacity={0.03} />
              <text x={xScale(15)} y={12} textAnchor="middle" fontSize={9} fill="#38bdf8" opacity={0.6}>
                LOW FATIGUE
              </text>
              <rect x={xScale(60)} y={0} width={xScale(85)-xScale(60)} height={IH}
                fill="#ef4444" opacity={0.04} />
              <text x={xScale(72)} y={12} textAnchor="middle" fontSize={9} fill="#ef4444" opacity={0.6}>
                HIGH FATIGUE
              </text>
            </g>

            {/* X axis */}
            <g transform={`translate(0,${IH})`}>
              <line x1={0} x2={IW} stroke="#1e293b" />
              {xTicks.map(t => (
                <g key={t} transform={`translate(${xScale(t)},0)`}>
                  <line y2={5} stroke="#334155" />
                  <text y={18} textAnchor="middle" fontSize={10} fill="#64748b">{t}</text>
                </g>
              ))}
              <text x={IW/2} y={42} textAnchor="middle" fontSize={11} fill="#475569" letterSpacing="0.1em">
                FATIGUE INDEX
              </text>
            </g>

            {/* Y axis */}
            <g>
              <line y1={0} y2={IH} stroke="#1e293b" />
              {yTicks.map(t => (
                <g key={t} transform={`translate(0,${yScale(t)})`}>
                  <line x2={-5} stroke="#334155" />
                  <text x={-10} textAnchor="end" dominantBaseline="middle" fontSize={10} fill="#64748b">{t}</text>
                </g>
              ))}
              <text
                transform={`translate(${-42},${IH/2}) rotate(-90)`}
                textAnchor="middle" fontSize={11} fill="#475569" letterSpacing="0.1em"
              >
                NET RATING
              </text>
            </g>

          </g>
        </svg>

        {/* Tooltip */}
        {tooltip && (
          <div style={{
            position:"absolute", left:tooltip.x, top:tooltip.y, pointerEvents:"none",
            background:"rgba(8,14,26,0.97)",
            border:`1px solid ${tooltip.pt.isWin ? "#4ade80" : "#f87171"}`,
            borderRadius:6, padding:"10px 14px", fontSize:11, lineHeight:1.8,
            color:"#e2e8f0", width:210, boxShadow:"0 4px 24px rgba(0,0,0,0.7)", zIndex:10
          }}>
            <div style={{ fontWeight:700, fontSize:13, color:"#f8fafc", marginBottom:2 }}>
              {TEAM_NAMES[tooltip.pt.team] ?? tooltip.pt.team}
            </div>
            <div style={{ color:"#64748b", fontSize:10, marginBottom:6 }}>
              {tooltip.pt.date} · {tooltip.pt.home_away==="H"?"Home":"Away"} vs {tooltip.pt.opponent}
            </div>
            <table style={{ borderCollapse:"collapse", width:"100%" }}>
              <tbody>
                {([
                  ["Result",        tooltip.pt.isWin == null ? "—" : tooltip.pt.isWin ? "Win" : "Loss"],
                  ["Fatigue Index", fmt(tooltip.pt.fi)],
                  ["Net Rating",    fmt(tooltip.pt.netrtg)],
                  ["Rest",          tooltip.pt.rest_days != null ? `${tooltip.pt.rest_days}d` : "—"],
                  ["Miles",         tooltip.pt.travel_miles != null ? `${tooltip.pt.travel_miles.toLocaleString()} mi` : "—"],
                  ["TZ crossed",    String(tooltip.pt.tz_crossed ?? "—")],
                ] as [string,string][]).map(([l,v]) => (
                  <tr key={l}>
                    <td style={{ color:"#64748b", paddingRight:10, fontSize:10 }}>{l}</td>
                    <td style={{ color:"#e2e8f0", textAlign:"right" }}>{v}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {/* Legend */}
        <div style={{
          position:"absolute", top:MARGIN.top+8, right:MARGIN.right+8,
          background:"rgba(8,14,26,0.9)", border:"1px solid #1e293b",
          borderRadius:6, padding:"8px 12px", fontSize:10
        }}>
          <div style={{ display:"flex", alignItems:"center", gap:6, marginBottom:5 }}>
            <div style={{ width:24, height:2.5, background:activeColor, borderRadius:1 }} />
            <span style={{ color:"#94a3b8" }}>LOESS trend</span>
          </div>
          <div style={{ display:"flex", alignItems:"center", gap:6, marginBottom:4 }}>
            <div style={{ width:8, height:8, borderRadius:"50%", background:"rgba(74,222,128,0.8)" }} />
            <span style={{ color:"#94a3b8" }}>Win</span>
          </div>
          <div style={{ display:"flex", alignItems:"center", gap:6 }}>
            <div style={{ width:8, height:8, borderRadius:"50%", background:"rgba(248,113,113,0.8)" }} />
            <span style={{ color:"#94a3b8" }}>Loss</span>
          </div>
        </div>
      </div>
    </div>
  );
}
